// Généré depuis Natural Earth 10 m — ne pas éditer à la main.
// Voir scripts/build-map.mjs.
//
// Projection Mercator, fenêtre -15..46°E / 21..53°N.

export const MAP_VIEW = {
  lngMin: -15,
  lngMax: 46,
  latMin: 21,
  latMax: 53,
  width: 2595.74,
  height: 1755.01,
  // Cadre auquel la caméra se mesure : élargir la fenêtre de données ne doit
  // pas changer ce que signifie un niveau de zoom.
  reference: { width: 2000, height: 1100.26 },
};

export function project(lng, lat) {
  const k = MAP_VIEW.width / (MAP_VIEW.lngMax - MAP_VIEW.lngMin);
  const mercY = (l) => (180 / Math.PI) * Math.log(Math.tan(Math.PI / 4 + (l * Math.PI) / 360));
  return {
    x: (lng - MAP_VIEW.lngMin) * k,
    y: (mercY(MAP_VIEW.latMax) - mercY(lat)) * k,
  };
}

